mapper.select:
select a.sort, b.sort nodeSort, a.id, a.node_id, b.node_name, action_name, a.project_id, leader_dept_id, leader_user_id, leader_user_name, submit_result, plan_completion_time, real_completion_time, action_state, reward, a.remark from mes3_project_management_action a left join mes3_project_management_node b on a.node_id=b.id where a.del_flag = 0
and a.project_id = #{projectId}
order by b.sort is null, b.sort asc, a.sort is null, a.sort asc

select a.project_id, month, week_number, sum(case when a.${column} is not null then 1 else 0 end) as weekTotal from mes3_mdm_week t left join mes3_project_management_action a on a.del_flag = 0 and a.${column} >= t.start_date and a.${column} < DATE_ADD(t.end_date, INTERVAL 1 DAY) where year = #{year} and month in
#{month}
group by a.project_id, month, week_number
